<!--vbase-->
<template>
  <div class="row full-width">
    <div class="col-sm-12 col-md-12 col-lg-12">
      <q-markup-table
        flat
        class="dashboard-table-style back-white"
        id="script_log_validation_table"
      >
        <thead>
          <tr class="table-header-text">
            <template
              v-for="(column, index) in table_columns"
              :key="column.name"
            >
              <th
                :data-index="index"
                :draggable="canDragDropColumn(column)"
                :dropzone="canDragDropColumn(column)"
                direction="horizontal"
                @dragstart="onDragStart($event, table_columns, index)"
                @drop.prevent="handleDrop($event, index)"
                @dragover.prevent="onDragOver($event, index)"
                @dragenter.prevent="onDragEnter"
                @dragleave.prevent="onDragLeave"
                :style="{ cursor: getIsDragging ? 'pointer' : 'move' }"
                :class="column?.class || ''"
              >
                <span v-if="column.name == 'actions'" class="cursor-default">{{
                  $t(column.label)
                }}</span>
                <span v-else class="q-pr-md">{{ $t(column.label) }}</span>
              </th>
            </template>
          </tr>
        </thead>
        <tbody>
          <template v-if="record.hasOwnProperty('script_execution')">
            <template
              v-for="(script, index) in record.script_execution as any[]"
              :key="index"
            >
              <tr @click="clickForDetail(script)" class="cursor-pointer">
                <template v-for="col in table_columns" :key="col.name">
                  <td v-if="col.name === 'name'" class="text-left">
                    {{ script.label }}
                  </td>
                  <td v-else-if="col.name === 'trigger_on'" class="text-left">
                    {{ script.trigger }}
                  </td>
                  <td v-else-if="col.name === 'status'" class="text-left">
                    <template v-if="script.success">
                      <q-icon name="check" color="green" size="20px">
                        <q-tooltip>{{ $t('execution_successfull') }}</q-tooltip>
                      </q-icon>
                    </template>
                    <template v-else>
                      <q-icon name="close" color="red" size="20px">
                        <q-tooltip>{{ $t('execution_failed') }}</q-tooltip>
                      </q-icon>
                    </template>
                  </td>
                  <td
                    v-else-if="col.name === 'last_executed_on'"
                    class="text-left"
                  >
                    {{ script.last_executed_on }}
                  </td>
                  <td v-else-if="col.name === 'time_spent'" class="text-left">
                    {{ script.time_spent }} sec
                  </td>
                  <td v-else class="text-center">
                    <!-- expand icon -->
                    <q-btn
                      flat
                      dense
                      round
                      @click.stop.prevent
                      icon="more_horiz"
                    >
                      <q-menu
                        auto-close
                        transition-show="jump-down"
                        transition-hide="jump-up"
                        anchor="bottom middle"
                        self="top middle"
                      >
                        <q-list dense style="min-width: 100px">
                          <q-item class="cursor-pointer">
                            <q-item-section
                              @click="handleOpenDialog(index)"
                              class="cursor-pointer"
                            >
                              {{ $t('deactivate') }}</q-item-section
                            >
                          </q-item>
                        </q-list>
                      </q-menu>
                    </q-btn>
                  </td>
                </template>
              </tr>
              <tr v-show="script.expand && !script.success">
                <td class="text-center no-padding-left-right" colspan="6">
                  <q-input
                    v-model="script.exception"
                    class="exceptption-text-area"
                    outlined
                    type="textarea"
                    readonly
                  />
                </td>
              </tr>

              <ConfirmDialog
                v-model="confirm_de_active_dialog"
                :message="$t('confirm_switch_active')"
                :confirm-label="$t('yes')"
                :cancel-label="$t('cancel')"
                @confirm="handleDisability"
              />
            </template>
          </template>
          <template v-else>
            <tr>
              <td colspan="5" class="text-h4 text-center">
                {{ $t('no_data_found') }}
              </td>
            </tr>
          </template>
        </tbody>
      </q-markup-table>
    </div>
  </div>
</template>

<script lang="ts">
import axios from 'axios';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useDocumentStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
import { notify } from 'src/components/notifications/notify';
import ConfirmDialog from 'src/supplier/pages/ConfirmDialog.vue';
import { isUserAdmin } from 'src/utils/UserDetails';
import { api, getAuthorizationToken } from 'pages/APIs';
import dragDropColumn from 'src/mixins/dragDropColumn';
import { docScriptApiService, documentListApiService } from 'src/services';
import { addOrgIdQueryString } from 'src/utils/organization/org_id_helper';
import { LocalStorage } from 'quasar';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, dragDropColumn],
  props: {},
  components: {
    ConfirmDialog,
  },
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.hideLoading();
        } else {
          this.showLoading();
        }
      },
    },
  },
  mounted: function () {
    this.initView();
    this.prepareColumns();
    this.initDragDropColumns('script_log_validation_table', 'label', [
      'actions',
    ]);
    document.addEventListener(
      'script_log_validation_table-column-drop',
      this.onDropColumns,
    );
  },
  unmounted() {
    document.removeEventListener(
      'script_log_validation_table-column-drop',
      this.onDropColumns,
    );
  },

  methods: {
    initView() {
      //  make list to show data
    },
    clickForDetail(record: any) {
      if (!record.hasOwnProperty('expand')) {
        record.expand = true;
      } else {
        record.expand = !record.expand;
      }
      logInfo(record);
    },
    prepareColumns() {
      const saved_columns = LocalStorage.getItem(
        'SCRIPT_LOG_VALIDATION_COLUMNS',
      ) as string;
      if (saved_columns) {
        let columns = JSON.parse(saved_columns);
        if (!isUserAdmin()) {
          columns = columns.filter((col: any) => col.name !== 'actions');
        }
        this.table_columns = columns;
      }
    },
    onDropColumns() {
      LocalStorage.set(
        'SCRIPT_LOG_VALIDATION_COLUMNS',
        JSON.stringify(this.table_columns),
      );
    },
    handleOpenDialog(index: number) {
      this.confirm_de_active_dialog = true;
      this.record_id = index as any;
    },
    async handleDisability() {
      try {
        this.processing = true;
        const script = this.record.script_execution[this.record_id];

        await docScriptApiService
          .updateActive(script.script_id, false)
          .then((response) => {
            if (!response.success) throw new Error(response.message);
          });

        await documentListApiService
          .restartExport(this.record.doc_id, false)
          .then((response) => {
            if (!response.success) throw new Error(response.message);
          });

        // after update script auto restart document
        let token: string = await getAuthorizationToken();
        const response = await axios.get(
          addOrgIdQueryString(api.restart_document + this.record.doc_id),
          {
            headers: {
              Authorization: token,
            },
          },
        );
        if (response.data.success) {
          this.$router.push('/dashboard');
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
  data() {
    return {
      record_id: ref('') as any,
      table_columns: [
        { label: 'name', name: 'name' },
        { label: 'trigger_on', name: 'trigger_on' },
        { label: 'status', name: 'status' },
        { label: 'last_executed_on', name: 'last_executed_on' },
        { label: 'time_spent', name: 'time_spent' },
        ...(isUserAdmin()
          ? [{ label: 'actions', name: 'actions', class: 'text-center' }]
          : []),
      ],
    };
  },
  setup() {
    const doc_store = useDocumentStore();
    const { record, doc_loaded, processing, confirm_de_active_dialog } =
      storeToRefs(doc_store);
    return {
      record,
      doc_loaded,
      processing,
      confirm_de_active_dialog,
    };
  },
});
</script>
<style scoped>
.cursor-not-allowed {
  cursor: not-allowed;
}
.cursor-pointer {
  cursor: pointer;
}
</style>
